export function contentInventory(){return Object.freeze({concepts:concepts.length,termItems:concepts.length,codeFamilies:itemFamilies.filter(f=>['c','java','python'].includes(f.language)).length,sqlFamilies:itemFamilies.filter(f=>f.language==='sql').length,calculationFamilies:itemFamilies.filter(f=>f.language==='calculation').length,scenarioFamilies:itemFamilies.filter(f=>f.language==='scenario').length,reasoningFamilies:itemFamilies.length,items:questionCodes.length});}
export function topicInventory(topic){const ids=new Set(topic.concepts),families=allFamilies.filter(f=>f.conceptIds.some(id=>ids.has(id)));return {concepts:topic.concepts.length,families:families.filter(f=>f.language!=='term').length,items:families.reduce((n,f)=>n+f.variants,0)};}
